const $=id=>document.getElementById(id),base=$('base'),ink=$('ink'),ctx=ink.getContext('2d');let pages=[],index=0,tool='pen',color='#29483b',size=3,scale=1,drawing=null,space=false,db;pdfjsLib.GlobalWorkerOptions.workerSrc='assets/pdf.worker.min.js';
function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',3000)}
const request=indexedDB.open('paperly-v1',1);request.onupgradeneeded=()=>request.result.createObjectStore('state');const ready=new Promise(resolve=>{request.onsuccess=()=>{db=request.result;resolve()};request.onerror=()=>resolve()});
