function fit(){scale=1;resize()}
function resize(){if(!pages[index])return;const width=Math.max(150,$('desk').clientWidth-(innerWidth<700?30:64))*scale;$('paper').style.width=width+'px';$('paper').style.height=width*pages[index].h/pages[index].w+'px';$('zoom').textContent=Math.round(scale*100)+'%'}
function thumbs(){const holder=$('pages');holder.replaceChildren();pages.forEach((p,i)=>{const el=document.createElement('div');el.className='thumb'+(i===index?' active':'');const img=document.createElement('img');img.src=p.src;const name=document.createElement('p');name.textContent=p.name;const n=document.createElement('small');n.textContent=`第 ${i+1} 页`;el.append(img,name,n);el.onclick=()=>show(i);holder.append(el)});$('count').textContent=String(pages.length).padStart(2,'0')}
let showToken=0;async function show(i){const token=++showToken;index=i;const p=pages[i],image=await loadImg(p.src);if(token!==showToken)return;base.width=ink.width=p.w;base.height=ink.height=p.h;base.getContext('2d').drawImage(image,0,0,p.w,p.h);$('docname').textContent=p.name;$('pageinfo').textContent=`第 ${i+1} / ${pages.length} 页`;thumbs();resize();redraw();buttons()}
