$('undo').onclick=()=>{const p=pages[index];if(p?.items.length){p.redo.push(p.items.pop());redraw();buttons();save()}};$('redo').onclick=()=>{const p=pages[index];if(p?.redo.length){p.items.push(p.redo.pop());redraw();buttons();save()}};$('clear').onclick=()=>{if(confirm('清空本页全部书写？试卷原图会保留。')){const p=pages[index];p.redo=[...p.items].reverse();p.items=[];redraw();buttons();save()}};$('plus').onclick=()=>{scale=Math.min(4,scale+.25);resize()};$('minus').onclick=()=>{scale=Math.max(.5,scale-.25);resize()};$('fit').onclick=fit;window.onresize=resize;document.onkeydown=e=>{if(e.target.matches('input,textarea'))return;if((e.ctrlKey||e.metaKey)&&e.key==='z'){e.preventDefault();$(e.shiftKey?'redo':'undo').click()}else if(e.code==='Space'){e.preventDefault();space=true}else if(!e.ctrlKey&&!e.metaKey){const t={b:'pen',e:'eraser',h:'highlight',t:'text'}[e.key];if(t)choose(t)}};document.onkeyup=e=>{if(e.code==='Space')space=false};window.onblur=()=>space=false;
$('import').onclick=$('add').onclick=()=>$('files').click();async function makePage(src,name){const img=await loadImg(src),max=2200,f=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*f);c.height=Math.round(img.height*f);c.getContext('2d').drawImage(img,0,0,c.width,c.height);return{src:c.toDataURL('image/jpeg',.92),name,w:c.width,h:c.height,items:[],redo:[]}}
let importing=false;async function importFiles(files){if(importing)return;importing=true;toast('正在打开试卷…');const first=pages.length;try{for(const file of files){try{if(file.type==='application/pdf'||/\.pdf$/i.test(file.name)){const pdf=await pdfjsLib.getDocument({data:await file.arrayBuffer()}).promise;for(let n=1;n<=pdf.numPages;n++){const p=await pdf.getPage(n),v=p.getViewport({scale:1}),view=p.getViewport({scale:Math.min(2,2200/Math.max(v.width,v.height))}),c=document.createElement('canvas');c.width=Math.ceil(view.width);c.height=Math.ceil(view.height);await p.render({canvasContext:c.getContext('2d'),viewport:view}).promise;pages.push({src:c.toDataURL('image/jpeg',.92),name:file.name+' · '+n,w:c.width,h:c.height,items:[],redo:[]});toast(`正在载入 PDF ${n} / ${pdf.numPages}`)}}else if(file.type.startsWith('image/')){const url=URL.createObjectURL(file);try{pages.push(await makePage(url,file.name))}finally{URL.revokeObjectURL(url)}}else throw Error('不支持此文件格式')}catch(e){toast(file.name+' 打开失败：'+e.message)}}if(pages.length>first){await show(first);await save();toast('试卷已导入，可以开始答题了')}}finally{importing=false;$('files').value=''}}$('files').onchange=e=>importFiles([...e.target.files]);$('desk').ondragover=e=>e.preventDefault();$('desk').ondrop=e=>{e.preventDefault();importFiles([...e.dataTransfer.files])};
async function composite(p){const c=document.createElement('canvas');c.width=p.w;c.height=p.h;const b=c.getContext('2d');b.fillStyle='white';b.fillRect(0,0,c.width,c.height);b.drawImage(await loadImg(p.src),0,0);const layer=document.createElement('canvas');layer.width=p.w;layer.height=p.h;renderItems(layer.getContext('2d'),p.items);b.drawImage(layer,0,0);return c}
$('export').onclick=()=>$('exportDialog').showModal();$('closeDialog').onclick=()=>$('exportDialog').close();$('png').onclick=async()=>{try{const c=await composite(pages[index]);const a=document.createElement('a');a.download='纸上-答卷-'+(index+1)+'.png';a.href=c.toDataURL('image/png');a.click();$('exportDialog').close();toast('答卷已导出')}catch{toast('导出失败，请重试')}};$('pdf').onclick=async()=>{try{toast('正在生成完整答卷…');$('pdf').disabled=true;let doc;for(let i=0;i<pages.length;i++){const p=pages[i],c=await composite(p),w=p.w*.24,h=p.h*.24;if(!doc)doc=new jspdf.jsPDF({orientation:w>h?'landscape':'portrait',unit:'mm',format:[w,h]});else doc.addPage([w,h],w>h?'landscape':'portrait');doc.addImage(c.toDataURL('image/jpeg',.95),'JPEG',0,0,w,h)}doc.save('纸上-完整答卷.pdf');$('exportDialog').close();toast('完整答卷已导出')}catch(e){toast('导出失败：'+e.message)}finally{$('pdf').disabled=false}};
(async()=>{await ready;if(db){pages=await new Promise(resolve=>{const r=db.transaction('state').objectStore('state').get('pages');r.onsuccess=()=>resolve(r.result||[]);r.onerror=()=>resolve([])})}if(!pages.length){pages=[await makePage('assets/sample.jpg','一年级数学 · 单元练习')];save()}await show(0)})().catch(e=>toast('载入失败：'+e.message));
